import{_ as i,o as t,c as o,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Science Working Group 2020-09-23","description":"","frontmatter":{"title":"Ceph Science Working Group 2020-09-23","date":"2020-09-23T00:00:00.000Z","updated":"2020-09-25T00:00:00.000Z","tags":["Ceph","分布式存储","存储集群","OpenStack","S3网关"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Science_Working_Group_2020-09-23.md","filePath":"posts/2020/Ceph_Science_Working_Group_2020-09-23.md","lastUpdated":1780460162000}'),n={name:"posts/2020/Ceph_Science_Working_Group_2020-09-23.md"};function l(r,e,s,p,c,u){return t(),o("div",null,[...e[0]||(e[0]=[a('<p>本次会议是Ceph Science Working Group于2020年9月23日举行的小型聚会。会议主要由使用Ceph的研究系统管理员或大型集群辅助管理员组成，旨在讨论与Ceph相关的任何话题。以下是会议的关键细节、主要议题、决定事项以及后续行动计划：</p><h4 id="主要议题与讨论内容" tabindex="-1">主要议题与讨论内容 <a class="header-anchor" href="#主要议题与讨论内容" aria-label="Permalink to &quot;主要议题与讨论内容&quot;">​</a></h4><ol><li><p><strong>近期故障报告</strong></p><ul><li>讨论了近期一次长达四小时的全面停电事件，以及由此导致的集群恢复问题。</li></ul></li><li><p><strong>Ceph Bug讨论</strong></p><ul><li>讨论了Ceph版本14.2.11和Octopus中的一些问题，如OSD map trimming逻辑错误和文件存储OSD清理问题。</li></ul></li><li><p><strong>Octopus版本迁移经验</strong></p><ul><li>分享了从Luminous升级到Nautilus的经验，特别是关于S3网关的升级。</li></ul></li><li><p><strong>OpenStack与S3集成</strong></p><ul><li>讨论了如何在OpenStack环境中集成S3，以及如何处理用户通过OpenStack管理S3凭证和配额的需求。</li></ul></li><li><p><strong>大容量文件管理问题</strong></p><ul><li>讨论了处理包含大量小文件的S3 bucket时可能遇到的管理和性能问题。</li></ul></li><li><p><strong>Ceph-CSI使用情况</strong></p><ul><li>讨论了Ceph CSI在Kubernetes环境中的使用情况，特别是与RBD和CephFS的集成。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>对于Ceph版本14.2.11和Octopus中的已知问题，建议社区成员关注并参与修复。</li><li>对于大容量文件管理问题，建议进一步研究和测试可能的优化措施。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续监控和报告Ceph版本中的bug和性能问题。</li><li>对于S3和OpenStack集成问题，建议进一步研究和分享最佳实践。</li><li>对于Ceph-CSI的使用，建议社区成员分享更多实际使用经验和配置建议。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论了所有预定议题后结束，下一次会议计划在两个月后的11月25日举行。</p><p>[改进后的总结中保留的关键词包括：Ceph, distributed storage, CRUSH algorithm, high availability, scalability, object storage, block storage, file system storage, consistency, decentralization, performance, bluestore, bluefs, rocksdb, OSD, MON, MDS, PG, RADOS, librados, libcephfs, cephfs, rbd, radosgw, RGW, RESTful API, authentication, authorization, encryption, erasure coding, replication, snapshots, clones, thin provisioning, iSCSI, Fibre Channel, NFS, CIFS, POSIX, monitoring, dashboard, management, orchestration, automation, integration, containerization, Kubernetes, Docker, virtualization, cloud computing, AWS, Azure, Google Cloud, hybrid cloud, multi-cloud, storage cluster, node, disk, SSD, HDD, JBOD, SAN, NAS, network, topology, failure domain, recovery, resilience, load balancing, caching, compression, deduplication, tiering, performance tuning, benchmarking, testing, validation]</p>',10)])])}const g=i(n,[["render",l]]);export{d as __pageData,g as default};
